uth_example:
head_dim, base = 8, 10_000
pairs = range(head_dim // 2)

thetas = {i: round(base ** (-(2 * i) / head_dim), 6) for i in pairs}

angles = {}
for pos in [1, 10, 100]:
    angles[pos] = [round(pos * thetas[i], 4) for i in pairs]

print("rotation speed per pair:", thetas)
for pos, a in angles.items():
    print(f"position {pos:>3}: angles {a}")      # pair 0 spins fast, pair 3 barely moves
